// ============================================================
// SLIDE CONTENT: Why AI Needs Nuclear Power
// 8 slides | FirstDropHQ | Bloomberg dark investor style
// ============================================================

const testRunId = `render_test_${new Date().toISOString().replace(/[:.]/g, '_')}`;

const slides = [
  {
    slideNumber: 1,
    type: 'hook',
    headline: 'AI Has a Power Problem',
    subheadline: 'The infrastructure crisis no one is talking about.',
    body: 'The AI revolution is devouring electricity at unprecedented speed. Data centre energy consumption is doubling every two years.',
    badge: 'HOOK',
    stat: null
  },
  {
    slideNumber: 2,
    type: 'data',
    headline: 'Data Centres Need Massive Electricity',
    subheadline: 'Scale most investors have not priced in.',
    body: 'A single large AI training run consumes 1+ GWh. By 2030, AI data centres may require 1,000 TWh/year \u2014 more than most nations consume today.',
    badge: 'DATA',
    stat: '1,000 TWh/yr by 2030'
  },
  {
    slideNumber: 3,
    type: 'analysis',
    headline: 'Why Renewables Alone Fall Short',
    subheadline: 'Intermittency vs. always-on AI demand.',
    body: 'Solar and wind are intermittent. AI inference demands 24/7 baseload power. Grid-scale battery storage remains economically unproven at the required scale.',
    badge: 'ANALYSIS',
    stat: null
  },
  {
    slideNumber: 4,
    type: 'catalyst',
    headline: 'Why Nuclear Is Back in Focus',
    subheadline: 'Big Tech is signing nuclear deals at record pace.',
    body: 'Nuclear delivers 24/7 carbon-free baseload. Microsoft, Google, and Amazon all signed nuclear power agreements in 2024 \u2014 a first for Big Tech.',
    badge: 'CATALYST',
    stat: '3 Big Tech nuclear deals in 2024'
  },
  {
    slideNumber: 5,
    type: 'stock',
    headline: 'Where OKLO Fits',
    subheadline: 'Small modular reactors for the AI age.',
    body: 'OKLO (NYSE: OKLO) is building small modular reactors targeting tech campuses and remote AI data centre deployments. Sam Altman serves as Chairman.',
    badge: 'OKLO \u25cf NYSE',
    stat: 'NYSE: OKLO'
  },
  {
    slideNumber: 6,
    type: 'supply_chain',
    headline: 'The Uranium & Fuel Supply Chain',
    subheadline: 'More reactors means tighter uranium supply.',
    body: 'Demand for nuclear fuel is structurally rising. Key names: Cameco (CCJ), Sprott Physical Uranium Trust (U.UN), NexGen Energy (NXE).',
    badge: 'SUPPLY CHAIN',
    stat: 'Uranium +300% since 2020'
  },
  {
    slideNumber: 7,
    type: 'risks',
    headline: 'Key Risks to Watch',
    subheadline: 'What could slow the nuclear thesis.',
    body: 'Regulatory delays. Construction cost overruns. SMR technology unproven at commercial scale. Uranium price volatility. Political and community opposition.',
    badge: 'RISKS',
    stat: null
  },
  {
    slideNumber: 8,
    type: 'cta',
    headline: 'Follow @FirstDropHQ',
    subheadline: 'The companies building the next decade.',
    body: 'We track AI Infrastructure \u00b7 Nuclear \u00b7 Semiconductors \u00b7 Quantum \u00b7 Robotics \u00b7 Energy Grid \u00b7 Data Centres',
    badge: 'FIRSTDROPHQ',
    stat: '@firstdrophq'
  }
];

return [{
  json: {
    testRunId,
    testCreatedAt: new Date().toISOString(),
    topic: 'Why AI Needs Nuclear Power',
    brand: 'FirstDropHQ',
    tagline: 'The companies building the next decade.',
    slideCount: slides.length,
    slides
  }
}];

// ============================================================
// TEMPLATE CONFIGURATION
// TODO: Replace the two template IDs with real values from
//       Blotato Dashboard > Visuals > Templates
// ============================================================

const input = $input.item.json;

const templates = [
  {
    testIndex: 1,
    templateName: 'Bloomberg Dark Finance',
    templateId: 'BLOTATO_TEMPLATE_1_ID',
    styleDescription: 'Dark background, white/gold typography, finance badge, data-heavy layout',
    targetAesthetic: 'Bloomberg Terminal / Dark finance dashboard'
  },
  {
    testIndex: 2,
    templateName: 'Dark News Ticker',
    templateId: 'BLOTATO_TEMPLATE_2_ID',
    styleDescription: 'Dark newsroom style, ticker tape accents, bold headlines, investment focus',
    targetAesthetic: 'Premium investment newsletter / CNBC dark mode'
  }
];

// Return one item per template so SplitInBatches loops over both
return templates.map(template => ({
  json: {
    ...template,
    testRunId: input.testRunId,
    testCreatedAt: input.testCreatedAt,
    topic: input.topic,
    brand: input.brand,
    tagline: input.tagline,
    slideCount: input.slideCount,
    slides: input.slides
  }
}));

// ============================================================
// BUILD BLOTATO VISUAL CREATE API PAYLOAD
// Records start time for render timing measurement.
// Adjust field names to match the actual Blotato API spec:
//   Blotato Dashboard > API Reference > Visual > Create
// ============================================================

const input = $input.item.json;
const startTime = Date.now();

const payload = {
  templateId: input.templateId,
  format: 'carousel',
  slideCount: input.slides.length,

  // Slide content array
  slides: input.slides.map(slide => ({
    slideNumber:  slide.slideNumber,
    headline:     slide.headline,
    subheadline:  slide.subheadline,
    body:         slide.body,
    badge:        slide.badge,
    stat:         slide.stat || null
  })),

  // Brand / account identity
  branding: {
    accountName: input.brand,
    tagline:     input.tagline,
    colorScheme: 'dark'
  },

  // Render settings
  settings: {
    aspectRatio:  '1:1',
    outputFormat: 'carousel',
    quality:      'high',
    publish:      false
  },

  // Audit / test metadata
  metadata: {
    testRunId:    input.testRunId,
    testIndex:    input.testIndex,
    topic:        input.topic,
    doNotPublish: true
  }
};

return [{
  json: {
    ...input,
    startTime,
    payload,
    payloadJson: JSON.stringify(payload, null, 2)
  }
}];

// ============================================================
// PROCESS BLOTATO API RESPONSE
// Calculates render time, extracts output URL and credit cost,
// formats the row for Google Sheets.
// ============================================================

const endTime = Date.now();

// Retrieve pre-HTTP context (startTime, templateName, payload, etc.)
const preData     = $node['Build API Payload'].json;
const apiResponse = $input.item.json;   // Blotato API response body

const renderTimeMs  = endTime - preData.startTime;
const renderTimeSec = parseFloat((renderTimeMs / 1000).toFixed(2));

// Extract output URL — try every common Blotato field name
const outputUrl = (
  apiResponse.url                 ||
  apiResponse.output_url          ||
  apiResponse.media_url           ||
  apiResponse.carousel_url        ||
  apiResponse.result?.url         ||
  apiResponse.data?.url           ||
  apiResponse.data?.output_url    ||
  'URL_NOT_IN_RESPONSE'
);

// Extract credit cost — try every common field name
const creditCost = (
  apiResponse.credits_used        ??
  apiResponse.creditCost          ??
  apiResponse.credits             ??
  apiResponse.cost                ??
  apiResponse.data?.credits_used  ??
  'CHECK_BLOTATO_DASHBOARD'
);

const status =
  apiResponse.status ||
  apiResponse.state  ||
  (apiResponse.error ? 'ERROR' : 'COMPLETED');

const errorMessage = apiResponse.error || apiResponse.message || null;

return [{
  json: {
    // Identification
    testRunId:          preData.testRunId,
    testIndex:          preData.testIndex,
    testDateTime:       new Date().toISOString(),

    // Template
    templateName:       preData.templateName,
    templateId:         preData.templateId,
    styleDescription:   preData.styleDescription,

    // Performance
    slideCount:         preData.slideCount,
    renderTimeMs,
    renderTimeSec,

    // Results
    creditCost,
    outputUrl,
    status,
    errorMessage,

    // Quality assessment (fill in manually after reviewing the carousel URL)
    visualQualityNotes: 'PENDING — open outputUrl and review visually',
    isPremiumLook:      'PENDING',
    recommendation:     'PENDING',

    // Full payloads for audit log
    fullRequestPayload: preData.payloadJson,
    rawApiResponse:     JSON.stringify(apiResponse, null, 2)
  }
}];

// ============================================================
// MONTHLY CREDIT COST ESTIMATES
// Calculates projected Blotato credit usage at 3 posting rates.
//
// !!! UPDATE avgCreditsPerCarousel after seeing the actual
//     credit cost in the test results above !!!
// ============================================================

// --- UPDATE THIS VALUE after reviewing test results ---
const avgCreditsPerCarousel = 10; // PLACEHOLDER — replace with actual credit cost
// -------------------------------------------------------

const scenarios = [
  { frequency: '1 post/day',  postsPerDay: 1, postsPerWeek: 7,  postsPerMonth: 30 },
  { frequency: '2 posts/day', postsPerDay: 2, postsPerWeek: 14, postsPerMonth: 61 },
  { frequency: '3 posts/day', postsPerDay: 3, postsPerWeek: 21, postsPerMonth: 91 }
];

return scenarios.map(s => ({
  json: {
    rowType:                   'CREDIT_ESTIMATE',
    estimatedAt:               new Date().toISOString(),
    frequency:                 s.frequency,
    postsPerDay:               s.postsPerDay,
    postsPerWeek:              s.postsPerWeek,
    postsPerMonth:             s.postsPerMonth,
    avgCreditsPerCarousel,
    estimatedMonthlyCredits:   s.postsPerMonth * avgCreditsPerCarousel,
    note: `avgCreditsPerCarousel is ${avgCreditsPerCarousel} (PLACEHOLDER). Update from render test results.`
  }
}));
